"""Regenerate indexable local guides from the reviewed launch data; no ratings invented."""
import json, html
from pathlib import Path
rows=json.loads(Path('data/lowell-launch.json').read_text(encoding='utf-8'))
guides=[('food-in-lowell-ma','Places to eat in Lowell, MA',lambda r:r['location_kind']=='street_address'),('food-trucks-in-lowell-ma','Food trucks serving Lowell & the Merrimack Valley',lambda r:r['kind']=='Food truck'),('restaurants-in-lowell-ma','Restaurants in Lowell, MA',lambda r:r['kind']=='Restaurant'),('bakeries-in-lowell-ma','Bakeries in Lowell, MA',lambda r:r['kind']=='Bakery'),('cafes-in-lowell-ma','Cafes in Lowell, MA',lambda r:r['kind']=='Cafe'),('tacos-in-lowell-ma','Find tacos in Lowell, MA',lambda r:'tacos' in r['cuisine'].lower())]
urls=['https://thestreetbite.com/']
for slug,title,predicate in guides:
 selected=[r for r in rows if predicate(r)]
 cards=[]
 for r in selected:
  e=lambda key:html.escape(str(r.get(key) or ''))
  cards.append(f'<article class="place-card"><span class="tag">{e("kind")}</span><h2>{e("name")}</h2><p>{e("cuisine")}</p><p>{e("address")} · {e("city")} {e("zip")}</p><p class="small">Public-source listing, unclaimed at import. Current hours and mobile parking must be confirmed with the business.</p><a class="button" href="/?place={e("source_key")}">View listing &amp; claim options ↗</a><a class="small" href="{e("source_url")}" target="_blank" rel="noopener">Listing source ↗</a></article>')
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | TheStreetBite</title><meta name="description" content="Explore public-source local dining listings, check current details with businesses, and discover owner check-ins on TheStreetBite."><link rel="canonical" href="https://thestreetbite.com/{slug}"><link rel="stylesheet" href="streetbite.css?v=discovery-2"></head><body><header><a class="brand brand-logo" href="/">TheStreetBite<span>.</span></a><nav><a href="/#find">Find nearby food</a><a href="list-business.html">For businesses ↗</a></nav></header><main class="business-main"><p class="eyebrow">LOWELL / MERRIMACK VALLEY LOCAL GUIDE</p><h1>{html.escape(title)}</h1><p class="intro">A starting point for your next local bite. These {len(selected)} listings were checked against public business or local tourism sources on November 16, 2026. No rankings, ratings, current opening hours or live parking are inferred from this list.</p><p>For distances, current owner check-ins and the latest ownership status, <a href="/#find">open the live directory</a>. Traveling trucks may have no confirmed stop near you.</p><section class="guide-grid">{''.join(cards)}</section><p class="small">Addresses are geocoded using the US Census geocoder. Public-source records can become outdated. Claim a listing through the directory; ownership changes require review.</p></main><footer><a href="/">TheStreetBite</a><a href="list-business.html">List or claim a business</a></footer></body></html>'''
 Path(slug+'.html').write_text(page,encoding='utf-8');urls.append('https://thestreetbite.com/'+slug)
Path('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+html.escape(u)+'</loc></url>' for u in urls)+'</urlset>',encoding='utf-8')
Path('robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://thestreetbite.com/sitemap.xml\n',encoding='utf-8')
print('Generated',len(guides),'indexable local guides and sitemap')
